using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Solutions;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline runs a tracked query over many entities; Optimized calls the
// agent-owned NoTrackingSolution.Run. Do not edit this file — edit
// Solutions/NoTracking.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class NoTrackingBenchmark
{
    private const int Year = 2024;
    private SqliteConnection _connection = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using var db = AppDbContext.Create(_connection);
        db.Database.EnsureCreated();
        SeedData.SeedInvoices(db, invoices: 40000, year: Year);

        EquivalenceGuard.SameResults(Baseline(), Optimized(), r => r.InvoiceId.ToString());
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<InvoiceRow> Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        var invoices = db.Invoices.Where(i => i.Year == Year).Include(i => i.Customer).ToList();
        return invoices.Select(i => new InvoiceRow(i.Id, i.Customer.Name, i.Amount)).ToList();
    }

    [Benchmark]
    public List<InvoiceRow> Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        return NoTrackingSolution.Run(db, Year);
    }
}
